function work_amount(string $value,string $currency): int {
 if(!preg_match(in_array($currency,['JPY','UGX','RWF'],true)?'/\A[0-9]{1,7}\z/':'/\A[0-9]{1,7}(?:\.[0-9]{1,2})?\z/',$value))throw new RuntimeException('Check the amount.');
 $parts=explode('.',$value);return (int)$parts[0]*100+(int)str_pad($parts[1]??'',2,'0');
}
function work_rpc(string $name,array $args): array {return api('/rest/v1/rpc/'.$name,$args,'POST',$_SESSION['auth']['access_token']);}
function work_input(string $name,string $label,string $type='text',string $value='',bool $required=true): void {static $count=0;$count++;$element=$name.'-'.$count;echo '<label for="'.esc($element).'">'.esc($label).'</label><input id="'.esc($element).'" name="'.esc($name).'" type="'.esc($type).'" value="'.esc($value).'"'.($required?' required':'').'>';}
function work_form(string $action,string $label,array $row=[]): void {echo '<details class="panel"><summary>'.esc($label).'</summary>';form_start();echo '<input type="hidden" name="action" value="'.esc($action).'">';if($row)echo '<input type="hidden" name="id" value="'.esc($row['id']).'"><input type="hidden" name="version" value="'.(int)($row['version']??0).'">';}
function work_end(string $label='Save'): void {echo '<button class="primary">'.esc($label).'</button></form></details>';}
