    $op='business_quote_write';$a=['p_id'=>$id,'p_version'=>$version,'p_action'=>'save','p_document'=>$doc,'p_expiry'=>(string)($_POST['expires_on']??'')];if($role==='manager')$a['authorization_reason']=(string)($_POST['reason']??'');break;
   case 'send':$op='business_quote_send';$a=['p_id'=>$id,'p_version'=>$version,'p_free_confirmed'=>isset($_POST['confirm_free'])];if($role==='manager')$a['authorization_reason']=(string)($_POST['reason']??'');break;
