   case 'invoice':$op='business_invoice_write';$a=['p_id'=>$id,'p_version'=>0,'p_action'=>'save','p_booking'=>(string)($_POST['booking']??''),'p_due'=>(string)($_POST['due_on']??'')];break;
   case 'issue':$op='business_invoice_write';$a=['p_id'=>$id,'p_version'=>$version,'p_action'=>'issue'];break;
   case 'payment':$op='business_invoice_payment';$a=['p_invoice'=>$id,'p_id'=>quote_uuid(),'p_amount'=>work_amount((string)($_POST['amount']??''),(string)($_POST['currency']??'ZAR')),'p_paid_on'=>(string)($_POST['paid_on']??''),'p_reference'=>(string)($_POST['reference']??'')];break;
